/**
 * @ohos/dsh-tool-office — create and read Office documents on the device.
 *
 * dsh's own Office stack cannot run here: `dsh-skill-office` asks for Python
 * plus a shell, and `dsh-office-kit` converts through a native LibreOffice (or
 * its WASM build) — both dead on a platform with no fork/exec, no native ELF
 * modules, and `--jitless` (no WebAssembly). This plugin takes the other road:
 * a .docx/.xlsx is a ZIP of XML, Node's `zlib` is compiled C (not WASM), so
 * generation and text extraction are pure JavaScript and stay inside the app.
 *
 * Three model-facing tools:
 *   office_read         — extract Markdown (docx) or TSV (xlsx) from a file
 *   office_write_docx   — Markdown subset → Word document
 *   office_write_xlsx   — CSV/TSV → one-sheet workbook
 *
 * Rendering the document for the user is the app's job (the native preview);
 * these tools only read and write bytes. All paths are fenced to the session
 * workspace, writes are staged+renamed, and `read-only` mode refuses writes
 * before touching the filesystem.
 */

import z from "@deepseek-ai/schemastery";
import { defineTool } from "@deepseek-ai/dsh-tools";
import { relative } from "node:path";

import { OfficeError } from "./lib/errors.js";
import { readDocx, buildDocx } from "./lib/docx.js";
import { readInside, writeInside } from "./lib/fsx.js";
import { buildXlsx, readXlsx } from "./lib/xlsx.js";

const name = "tool-office-ohos";
const inject = ["tools", "fs", "workingDirectory"];

const Config = z.object({
	/** Refuse to load a document bigger than this; a phone has no swap. */
	maxReadBytes: z.number().default(20 * 1024 * 1024),
	/** Default cap for the text returned to the model. */
	maxTextChars: z.number().default(30000),
	/** Hard ceiling for the text cap (the model may ask for less). */
	maxTextCharsLimit: z.number().default(100000)
});

/** What a path should be called in tool output. */
function displayPath(cwd, absolute) {
	const rel = relative(cwd, absolute);
	return rel.length === 0 || rel.startsWith("..") ? absolute : rel;
}

function extensionOf(path) {
	const base = path.substring(path.lastIndexOf("/") + 1);
	const dot = base.lastIndexOf(".");
	return dot < 0 ? "" : base.substring(dot + 1).toLowerCase();
}

/** Append the Office extension, or reject a legacy binary format by name. */
function requireExtension(path, extension, legacy) {
	const ext = extensionOf(path);
	if (ext === extension) return path;
	if (ext === legacy) {
		throw new OfficeError(
			`legacy .${legacy} files cannot be read on device; save it as .${extension} first`,
			"OFFICE_UNSUPPORTED"
		);
	}
	if (ext.length === 0) return `${path}.${extension}`;
	throw new OfficeError(`expected a .${extension} path, got .${ext}: ${path}`, "OFFICE_BAD_ARGS");
}

function textLimit(value, fallback, limit) {
	if (typeof value !== "number" || !Number.isFinite(value) || value <= 0) return fallback;
	return Math.max(1000, Math.min(limit, Math.floor(value)));
}

function requireText(value, field) {
	if (typeof value !== "string" || value.trim().length === 0) {
		throw new OfficeError(`${field} is required and must be a non-empty string`, "OFFICE_BAD_ARGS");
	}
	return value;
}

/** Read one document and return the model-facing text plus shape facts. */
async function readOffice(ctx, exec, args, caps) {
	const input = requireText(args.path, "path").trim();
	const limit = textLimit(args.max_chars, caps.maxTextChars, caps.maxTextCharsLimit);
	const ext = extensionOf(input);
	if (ext === "doc" || ext === "xls" || ext === "ppt") {
		throw new OfficeError(
			`legacy .${ext} files are not supported; save the document as .${ext}x (OOXML) and retry`,
			"OFFICE_UNSUPPORTED"
		);
	}
	if (ext !== "docx" && ext !== "xlsx" && ext !== "pptx") {
		throw new OfficeError(`unsupported Office extension: ${input}`, "OFFICE_UNSUPPORTED");
	}
	if (ext === "pptx") {
		throw new OfficeError(
			"PPTX reading is not supported yet; ask the user to share the slides as PDF, or inspect the .pptx as a ZIP",
			"OFFICE_UNSUPPORTED"
		);
	}
	const file = await readInside(ctx, exec, input, caps.maxReadBytes);
	const shown = displayPath(file.cwd, file.path);
	if (ext === "docx") {
		const result = readDocx(file.bytes, { maxChars: limit });
		return {
			path: shown,
			kind: "docx",
			text: result.text + (result.truncated ? "\n\n…（内容超出上限，已截断）" : ""),
			truncated: result.truncated,
			bytes: file.bytes.length
		};
	}
	const result = readXlsx(file.bytes, {
		sheet: typeof args.sheet === "string" && args.sheet.trim().length > 0 ? args.sheet.trim() : undefined,
		maxChars: limit
	});
	return {
		path: shown,
		kind: "xlsx",
		text: result.text + (result.truncated ? "\n\n…（内容超出上限，已截断）" : ""),
		truncated: result.truncated,
		sheets: result.sheets.map((sheet) => sheet.name),
		bytes: file.bytes.length
	};
}

/** Create a Word document from the supported Markdown subset. */
async function writeDocx(ctx, exec, args) {
	const markdown = typeof args.markdown === "string" ? args.markdown : "";
	if (markdown.trim().length === 0) throw new OfficeError("markdown is required", "OFFICE_BAD_ARGS");
	const path = requireExtension(requireText(args.path, "path").trim(), "docx", "doc");
	const result = buildDocx(markdown);
	const written = await writeInside(ctx, exec, path, result.buffer);
	return {
		path: displayPath(written.cwd, written.path),
		bytes: written.bytes,
		paragraphs: result.stats.paragraphs,
		headings: result.stats.headings,
		lists: result.stats.lists,
		tables: result.stats.tables
	};
}

/** Create a one-sheet workbook from CSV/TSV. */
async function writeXlsx(ctx, exec, args) {
	const csv = typeof args.csv === "string" ? args.csv : "";
	if (csv.trim().length === 0) throw new OfficeError("csv is required", "OFFICE_BAD_ARGS");
	const path = requireExtension(requireText(args.path, "path").trim(), "xlsx", "xls");
	const sheetName = typeof args.sheet_name === "string" ? args.sheet_name.trim() : "";
	const result = buildXlsx(csv, sheetName.length > 0 ? { sheetName } : {});
	const written = await writeInside(ctx, exec, path, result.buffer);
	return {
		path: displayPath(written.cwd, written.path),
		bytes: written.bytes,
		rows: result.rows,
		columns: result.columns,
		sheet: result.sheetName,
		formulas: result.formulas
	};
}

function registerRead(ctx, caps) {
	ctx.tools.register(defineTool({
		name: "office_read",
		description:
			"Read a Word (.docx) or Excel (.xlsx) document from the session workspace and return its content as Markdown/TSV. " +
			"Use it to answer questions about a document the user put in the workspace. " +
			"Word content keeps headings, lists, links' text, tables and emphasis; Excel content is one `## Sheet: name` block per sheet, " +
			"with formulas shown as `=FORMULA` and date-formatted cells as ISO dates. " +
			"Legacy .doc/.xls/.ppt and .pptx are not supported — ask the user to save as .docx/.xlsx or share a PDF.",
		parameters: {
			path: {
				type: "string",
				required: true,
				description: "Workspace-relative (or inside-workspace absolute) path to the .docx/.xlsx file."
			},
			sheet: {
				type: "string",
				description: "xlsx only: read one sheet by name. Omit to read every sheet."
			},
			max_chars: {
				type: "number",
				description: "Cap the returned text (default 30000, minimum 1000)."
			}
		},
		timeoutMs: 30000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					path: { type: "string", required: true },
					kind: { type: "string", required: true },
					text: { type: "string", required: true },
					truncated: { type: "boolean", required: true },
					bytes: { type: "number" },
					sheets: { type: "array", items: { type: "string" } }
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: `（${value.kind} · ${value.bytes ?? "?"} 字节）${value.path}\n\n${value.text}`
			}]
		},
		presentCall: (args) => ({
			card: "generic",
			title: "Read Office document",
			kind: "read",
			...args.path === undefined ? {} : { rawInput: args.path }
		}),
		isConcurrencySafe: () => true,
		execute: (args, exec) => readOffice(ctx, exec, args, caps)
	}));
}

function registerWriteDocx(ctx) {
	ctx.tools.register(defineTool({
		name: "office_write_docx",
		description:
			"Create a Word .docx in the session workspace from Markdown. " +
			"Supported: `#`/`##`/`###` headings, paragraphs, `-` bullets, `1.` numbered lists, pipe tables, " +
			"`**bold**`, `*italic*`, `` `code` ``, `>` quotes and ``` fenced code ```. " +
			"Other Markdown is kept as plain paragraphs. The file is overwritten if it exists; " +
			"give a path ending in .docx (a missing extension is appended).",
		parameters: {
			path: {
				type: "string",
				required: true,
				description: "Workspace-relative path for the new .docx, e.g. \"reports/weekly.docx\"."
			},
			markdown: {
				type: "string",
				required: true,
				description: "Document body in the supported Markdown subset."
			}
		},
		timeoutMs: 30000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					path: { type: "string", required: true },
					bytes: { type: "number", required: true },
					paragraphs: { type: "number", required: true },
					headings: { type: "number", required: true },
					lists: { type: "number", required: true },
					tables: { type: "number", required: true }
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: `已生成 Word 文档：${value.path}（${value.bytes} 字节 · ${value.paragraphs} 段 · ${value.headings} 标题 · ${value.lists} 列表项 · ${value.tables} 表）`
			}]
		},
		presentCall: (args) => ({
			card: "generic",
			title: "Create Word document",
			kind: "write",
			...args.path === undefined ? {} : { rawInput: args.path }
		}),
		execute: (args, exec) => writeDocx(ctx, exec, args)
	}));
}

function registerWriteXlsx(ctx) {
	ctx.tools.register(defineTool({
		name: "office_write_xlsx",
		description:
			"Create a one-sheet Excel .xlsx in the session workspace from CSV or TSV text. " +
			"The delimiter is sniffed (comma/tab/semicolon); quoted fields may contain commas and newlines. " +
			"Plain numbers become numeric cells, values with a leading zero stay text, and a cell starting with `=` becomes a formula " +
			"that Excel/WPS calculates on open. The first row is bold and frozen as a header. " +
			"The file is overwritten if it exists; a missing .xlsx extension is appended.",
		parameters: {
			path: {
				type: "string",
				required: true,
				description: "Workspace-relative path for the new .xlsx, e.g. \"reports/costs.xlsx\"."
			},
			csv: {
				type: "string",
				required: true,
				description: "Sheet content as CSV/TSV. First row is the header."
			},
			sheet_name: {
				type: "string",
				description: "Sheet tab name (default Sheet1, max 31 chars)."
			}
		},
		timeoutMs: 30000,
		output: {
			schema: {
				type: "object",
				additionalProperties: false,
				properties: {
					path: { type: "string", required: true },
					bytes: { type: "number", required: true },
					rows: { type: "number", required: true },
					columns: { type: "number", required: true },
					sheet: { type: "string", required: true },
					formulas: { type: "number", required: true }
				}
			},
			render: (_args, value) => [{
				type: "text",
				text: `已生成 Excel 工作簿：${value.path}（${value.bytes} 字节 · ${value.rows} 行 × ${value.columns} 列 · 工作表「${value.sheet}」${value.formulas > 0 ? ` · ${value.formulas} 个公式` : ""}）`
			}]
		},
		presentCall: (args) => ({
			card: "generic",
			title: "Create spreadsheet",
			kind: "write",
			...args.path === undefined ? {} : { rawInput: args.path }
		}),
		execute: (args, exec) => writeXlsx(ctx, exec, args)
	}));
}

function apply(ctx, config) {
	const resolved = config === undefined ? Config() : config;
	const caps = {
		maxReadBytes: resolved.maxReadBytes,
		maxTextChars: resolved.maxTextChars,
		maxTextCharsLimit: resolved.maxTextCharsLimit
	};
	registerRead(ctx, caps);
	registerWriteDocx(ctx);
	registerWriteXlsx(ctx);
}

export {
	Config,
	apply,
	displayPath,
	extensionOf,
	inject,
	name,
	readOffice,
	requireExtension,
	textLimit,
	writeDocx,
	writeXlsx
};
